// The flags, name and value both taken from upstream's own `bitflags`
// block. `MF_TRANSLATION` is a two-bit colour field rather than a bit,
// which is the reason these are not `1 << position`.
/// DOOM's `MF_SPECIAL`.
pub const MF_SPECIAL: u32 = 0x1;
/// DOOM's `MF_SOLID`.
pub const MF_SOLID: u32 = 0x2;
/// DOOM's `MF_SHOOTABLE`.
pub const MF_SHOOTABLE: u32 = 0x4;
/// DOOM's `MF_NOSECTOR`.
pub const MF_NOSECTOR: u32 = 0x8;
/// DOOM's `MF_NOBLOCKMAP`.
pub const MF_NOBLOCKMAP: u32 = 0x10;
/// DOOM's `MF_AMBUSH`.
pub const MF_AMBUSH: u32 = 0x20;
/// DOOM's `MF_JUSTHIT`.
pub const MF_JUSTHIT: u32 = 0x40;
/// DOOM's `MF_JUSTATTACKED`.
pub const MF_JUSTATTACKED: u32 = 0x80;
/// DOOM's `MF_SPAWNCEILING`.
pub const MF_SPAWNCEILING: u32 = 0x100;
/// DOOM's `MF_NOGRAVITY`.
pub const MF_NOGRAVITY: u32 = 0x200;
/// DOOM's `MF_DROPOFF`.
pub const MF_DROPOFF: u32 = 0x400;
/// DOOM's `MF_PICKUP`.
pub const MF_PICKUP: u32 = 0x800;
/// DOOM's `MF_NOCLIP`.
pub const MF_NOCLIP: u32 = 0x1000;
/// DOOM's `MF_SLIDE`.
pub const MF_SLIDE: u32 = 0x2000;
/// DOOM's `MF_FLOAT`.
pub const MF_FLOAT: u32 = 0x4000;
/// DOOM's `MF_TELEPORT`.
pub const MF_TELEPORT: u32 = 0x8000;
/// DOOM's `MF_MISSILE`.
pub const MF_MISSILE: u32 = 0x10000;
/// DOOM's `MF_DROPPED`.
pub const MF_DROPPED: u32 = 0x20000;
/// DOOM's `MF_SHADOW`.
pub const MF_SHADOW: u32 = 0x40000;
/// DOOM's `MF_NOBLOOD`.
pub const MF_NOBLOOD: u32 = 0x80000;
/// DOOM's `MF_CORPSE`.
pub const MF_CORPSE: u32 = 0x100000;
/// DOOM's `MF_INFLOAT`.
pub const MF_INFLOAT: u32 = 0x200000;
/// DOOM's `MF_COUNTKILL`.
pub const MF_COUNTKILL: u32 = 0x400000;
/// DOOM's `MF_COUNTITEM`.
pub const MF_COUNTITEM: u32 = 0x800000;
/// DOOM's `MF_SKULLFLY`.
pub const MF_SKULLFLY: u32 = 0x1000000;
/// DOOM's `MF_NOTDMATCH`.
pub const MF_NOTDMATCH: u32 = 0x2000000;
/// DOOM's `MF_TRANSLATION`.
pub const MF_TRANSLATION: u32 = 0xC000000;

/// One kind of thing a map can place.
pub struct Kind {
    /// What a THING record calls it, or -1 for something only spawned
    /// by the game -- a rocket has no number because no map places one.
    pub doomednum: i16,
    pub spawn: u16,
    pub see: u16,
    pub pain: u16,
    pub melee: u16,
    pub missile: u16,
    pub death: u16,
    pub xdeath: u16,
    pub raise: u16,
    pub health: i16,
    pub reaction: i16,
    pub painchance: i16,
    /// Units per tic for anything that walks, and **fixed point** for
    /// anything that flies.
    ///
    /// One field with two units in it, which is DOOM's own and not an
    /// artefact of this generator: a monster's speed is an integer
    /// number of units it tries to move, while a missile's is a
    /// `fixed_t` added to its position directly, so a rocket reads
    /// 655360 where an imp reads 8. That is 10 << 16, and the reason
    /// this is `i32` -- 655360 does not fit in the `i16` every other
    /// number here fits in, which is the only reason anybody notices.
    /// A caller that reads a missile's speed as units per tic gets a
    /// rocket travelling ten thousand times too fast.
    pub speed: i32,
    pub radius: i16,
    pub height: i16,
    /// What damage has to shift to knock this back.
    ///
    /// A divisor rather than a weight, so ten million is not an outlier
    /// to be clamped -- it is how DOOM spells *immovable*, and Commander
    /// Keen and the boss brain both carry it because they hang in place
    /// and being shot must not move them. It is the second field here
    /// that will not fit in an `i16`, and for a completely different
    /// reason from the first.
    pub mass: i32,
    pub damage: i16,
    pub flags: u32,
}

