/// Which kind carries a doomednum, or nothing.
///
/// A linear scan, because it runs once per *distinct* thing kind when a
/// level loads and never per frame. DOOM does the same.
pub fn kind_of(doomednum: i16) -> Option<&'static Kind> {
    KINDS.iter().find(|k| k.doomednum == doomednum)
}

/// The sprite name and frame letter a state shows, or nothing.
///
/// **State 0 is  and draws nothing.** It is DOOM's no-state, and
/// several kinds sit in it permanently -- a teleport destination is a
/// real thing with a real doomednum whose whole job is to be a marker.
/// The row is not blank though:  carries 
/// because the array needs *something* there, so a reader that trusted
/// the fields would draw an imp on every teleport pad in the game.
pub fn frame_of(state: u16) -> Option<(&'static str, u8)> {
    if state == 0 {
        return None;
    }
    let s = STATES.get(state as usize)?;
    // The top bit is fullbright and is not part of the letter. What is
    // left is a frame *number*, and the lump is named by the letter at
    // that offset from `A` -- which past 25 leaves the alphabet and
    // carries on into `[`, `\` and `]`, exactly as id's own names do.
    let letter = b'A' + (s.frame & 0x7FFF) as u8;
    Some((SPRITES.get(s.sprite as usize)?, letter))
}

/// Whether a state draws at full brightness whatever the room is lit to.
///
/// A muzzle flash, a plasma bolt, an explosion. Nothing reads it yet --
/// it is one bit of the field `frame_of` masks off, and dropping it here
/// would mean regenerating the table when a projectile first needs it.
pub fn fullbright(state: u16) -> bool {
    STATES.get(state as usize).is_some_and(|s| s.frame & 0x8000 != 0)
}

